import { t, translateError } from './i18n.mjs';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function initMemberNotifications({modal,toast}){
 document.addEventListener('click',async event=>{if(!event.target.closest('[data-notifications]'))return;try{const response=await fetch('/api/notifications',{credentials:'same-origin',cache:'no-store'}),result=await response.json();if(!response.ok)throw Error(result.error||t("Could not load notifications.","Không tải được thông báo.","알림을 불러올 수 없습니다."));const items=result.notifications;modal(`<div class="eyebrow">DEBTFREELATELY</div><h2>${t("Your notifications","Thông báo của bạn","내 알림")}</h2><div class="member-notification-list">${items.length?items.map(item=>`<article class="member-notification ${item.read?'':'unread'}"><small>${e(new Date(item.createdAt).toLocaleString(t("en-US","vi-VN","ko-KR")))}${item.read?'':t(" · New"," · Mới"," · 새 알림")}</small><p>${e(item.message)}</p></article>`).join(''):'<p>'+t("You have no notifications from the admin.","Bạn chưa có thông báo từ admin.","관리자가 보낸 알림이 없습니다.")+'</p>'}</div>`);const unread=items.filter(item=>!item.read).map(item=>item.id);if(unread.length){const marked=await fetch('/api/notifications/read',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:unread})});if(!marked.ok)toast(t("Notifications opened, but their read status could not be updated.","Đã mở thông báo nhưng chưa cập nhật trạng thái đã đọc.","알림을 열었지만 읽음 상태를 업데이트할 수 없습니다."));}}catch(error){toast(translateError(error.message));}});
}
